  $readmemh("work/results/l5_target_oproj/vectors/weights_bf16.memh",weights);$readmemh("work/results/l5_target_norm2/vectors/weight.memh",nw);$readmemh({dir,"/attention.memh"},ia);$readmemh({dir,"/current.memh"},ic);$readmemh({dir,"/oproj.memh"},eo);$readmemh({dir,"/residual1.memh"},er);$readmemh({dir,"/norm2.memh"},en);for(int i=0;i<24576;i++)begin attention[i*32+:32]=ia[i];current[i*32+:32]=ic[i];end for(int i=0;i<1536;i++)rw[i*32+:32]=nw[i];repeat(3)@(posedge clk);rst_n=1;
  st=cycles;for(int tile=0;tile<48;tile++)begin clear512(cur);for(int k=0;k<1536;k++)begin for(int row=0;row<16;row++)aa[row*16+:16]=bf(attention[(row*1536+k)*32+:32]);for(int c=0;c<32;c++)ab[c*16+:16]=weights[k*1536+tile*32+c];ac=cur;@(negedge clk);aiv=1;do@(posedge clk);while(!air);@(negedge clk);aiv=0;do@(posedge clk);while(!(aov&&aor));@(negedge clk);cur=ao;afor|=af;end for(int row=0;row<16;row++)for(int c=0;c<32;c++)oproj[(row*1536+tile*32+c)*32+:32]=cur[(row*32+c)*32+:32];end matrix_cycles=cycles-st;for(int i=0;i<24576;i++)if(oproj[i*32+:32]!==eo[i])$fatal(1,"q128 oproj batch=%0d i=%0d",batch_index,i);
